use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use serde::Serialize;
use std::collections::BTreeMap;

const BILLING_UNIT_SECONDS: i64 = 900;
const MINIMUM_BILLABLE_SECONDS: i64 = 1800;

#[derive(Debug, PartialEq, Eq)]
struct MonthlyInvoice {
    months: BTreeMap<String, i64>,
    total_billable_seconds: i64,
}

#[derive(Serialize)]
struct MonthlyInvoiceJson {
    months: Vec<MonthlyInvoiceMonth>,
    total_billable_seconds: i64,
}

#[derive(Serialize)]
struct MonthlyInvoiceMonth {
    month: String,
    billable_seconds: i64,
}

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let invoice = calculate_invoice(&entries);

        if json {
            let output = MonthlyInvoiceJson {
                months: invoice
                    .months
                    .iter()
                    .map(|(month, seconds)| MonthlyInvoiceMonth {
                        month: month.clone(),
                        billable_seconds: *seconds,
                    })
                    .collect(),
                total_billable_seconds: invoice.total_billable_seconds,
            };
            println!(
                "{}",
                serde_json::to_string(&output).expect("failed to serialize invoice")
            );
        } else if invoice.months.is_empty() {
            println!("(no data)");
        } else {
            for (month, seconds) in &invoice.months {
                println!("{month}  {seconds}s");
            }
            println!("Total  {}s", invoice.total_billable_seconds);
        }

        Ok(())
    }
}

fn calculate_invoice(entries: &[TimeEntry]) -> MonthlyInvoice {
    let mut months = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.stop.is_none() {
            continue;
        }

        let rounded_seconds = ((entry.duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS)
            * BILLING_UNIT_SECONDS;
        let billed_seconds = rounded_seconds.max(MINIMUM_BILLABLE_SECONDS);
        let month = entry.start.format("%Y-%m").to_string();
        *months.entry(month).or_insert(0) += billed_seconds;
    }

    let total_billable_seconds = months.values().sum();
    MonthlyInvoice {
        months,
        total_billable_seconds,
    }
}

#[cfg(test)]
mod tests {
    use super::{calculate_invoice, MonthlyInvoice};
    use crate::models::TimeEntry;
    use chrono::{DateTime, Utc};
    use std::collections::BTreeMap;

    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
        TimeEntry {
            id: 1,
            description: String::new(),
            start: start.parse::<DateTime<Utc>>().unwrap(),
            stop: stopped.then(|| start.parse::<DateTime<Utc>>().unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn groups_stopped_billable_entries_by_utc_month_and_applies_invoice_rule() {
        let result = calculate_invoice(&[
            entry("2024-02-01T00:00:00Z", 1, true, true),
            entry("2024-02-01T01:00:00Z", 901, true, true),
            entry("2024-01-31T23:30:00-02:00", 1800, true, true),
            entry("2024-02-01T02:00:00Z", 3600, false, true),
            entry("2024-02-01T03:00:00Z", 3600, true, false),
        ]);

        assert_eq!(
            result,
            MonthlyInvoice {
                months: BTreeMap::from([("2024-02".to_string(), 5400),]),
                total_billable_seconds: 5400,
            }
        );
    }

    #[test]
    fn empty_invoice_has_zero_total() {
        assert_eq!(
            calculate_invoice(&[]),
            MonthlyInvoice {
                months: BTreeMap::new(),
                total_billable_seconds: 0,
            }
        );
    }
}
